\ir ../drizzle/migrations/0036_seed_legacy_houses_state.sql
\ir ../drizzle/migrations/0041_seed_complete_noble_house_possessions.sql
\ir ../drizzle/migrations/0042_reconcile_house_workbooks.sql
SELECT pg_temp.assert((SELECT version=8 AND state->'base'->>'lands'='20' FROM noble_house_sheets WHERE house_id='workbook-ashkar'),'upgrade intact 0041 snapshot and increment version');
SELECT pg_temp.assert((SELECT version=4 FROM noble_house_sheets WHERE house_id='workbook-everlost'),'upgrade intact 0036 snapshot');
SELECT pg_temp.assert((SELECT version=9 AND state->>'treasury'='123' FROM noble_house_sheets WHERE house_id='workbook-grantass'),'preserve edited house');
SELECT pg_temp.assert((SELECT status='needs_review' FROM noble_house_workbook_imports WHERE house_key='grantass'),'record edited-house conflict');
SELECT pg_temp.assert((SELECT status='ambiguous' FROM noble_house_workbook_imports WHERE house_key='silversky'),'reject ambiguous names');
SELECT pg_temp.assert(NOT EXISTS(SELECT 1 FROM noble_house_sheets WHERE house_id LIKE 'workbook-silversky%'),'do not choose first matching house');
SELECT pg_temp.assert((SELECT count(*)=4 FROM noble_house_ledger WHERE action='Conciliação das fichas 29/10/2026'),'one audited operation per changed house');
SELECT pg_temp.assert((SELECT before_state->>'houseId'='workbook-ashkar' AND after_state->>'houseId'='workbook-ashkar' FROM noble_house_ledger WHERE house_id='workbook-ashkar'),'complete before and after snapshots');
SELECT pg_temp.assert((SELECT state->'base'->>'wealth'='51' FROM noble_house_sheets WHERE house_id='workbook-fewmerry'),'include initial bonuses');
SELECT pg_temp.assert((SELECT h->'costs'->0->>'amount'='5' FROM noble_house_sheets, LATERAL jsonb_array_elements(state->'holdings') h WHERE house_id='workbook-erdenor' AND h->>'id'='hold-erdenor-road-2'),'road cost follows E28');
UPDATE noble_house_sheets SET state=jsonb_set(state,'{treasury}','456'),version=version+1 WHERE house_id='workbook-ashkar';
DELETE FROM campaign_houses WHERE id='workbook-silversky-duplicate';
\ir ../drizzle/migrations/0042_reconcile_house_workbooks.sql
SELECT pg_temp.assert((SELECT version=9 AND state->>'treasury'='456' FROM noble_house_sheets WHERE house_id='workbook-ashkar'),'retry preserves later changes');
SELECT pg_temp.assert((SELECT count(*)=5 FROM noble_house_ledger WHERE action='Conciliação das fichas 29/10/2026'),'retry creates only newly resolved house');
SELECT pg_temp.assert((SELECT status='applied' FROM noble_house_workbook_imports WHERE house_key='silversky'),'resolved ambiguity can import');
SELECT pg_temp.assert(NOT has_table_privilege('anon','noble_house_workbook_imports','SELECT'),'audit is not public');
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert((SELECT count(*)=0 FROM noble_house_workbook_imports),'ordinary reader cannot inspect import audit');
RESET ROLE;
ROLLBACK;
